mapper.select:
WITH page_assets AS ( SELECT a.asset_id FROM media_asset a WHERE a.space_id=#{query.spaceId} AND a.deleted_at IS NULL AND a.status='READY' AND (a.owner_id=#{query.accountId} OR a.access_scope='SPACE' OR a.library_visible=true) AND a.library_visible=true AND a.media_type=#{query.mediaType}
AND (a.created_at<#{query.cursorCreatedAt} OR (a.created_at=#{query.cursorCreatedAt} AND a.asset_id<#{query.cursorId}))
ORDER BY a.created_at DESC,a.asset_id DESC LIMIT #{query.limit} ) SELECT FROM page_assets p JOIN media_asset a ON a.asset_id=p.asset_id JOIN diary_space s ON s.space_id=a.space_id LEFT JOIN media_variant v ON v.asset_id=a.asset_id AND v.deleted_at IS NULL AND v.status='READY' ORDER BY a.created_at DESC,a.asset_id DESC, FIELD(v.variant_type,'THUMBNAIL','POSTER','ORIGINAL','TRANSCODED','WAVEFORM'),v.variant_id
